// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: admin (the true admin EOA) and proposedOwner (the _owner argument)
    function testFuzz_property(address admin, address proposedOwner) public {
        // keep addresses in wide admissible domain but avoid zero-address for clarity
        vm.assume(admin != address(0));
        vm.assume(proposedOwner != address(0));
        // Deploy a forwarder that will call c.setOwner on behalf of admin.
        Forwarder f = new Forwarder();

        // Fund the forwarder so it can make calls if needed (not strictly needed here)
        vm.deal(address(f), 1 ether);

        // The reference C stores owner = _owner when onlyAdmin calls setOwner.
        // We need the admin to be the contract's admin (set in constructor to deployer), but c was deployed by this test contract.
        // So to make 'admin' be the admin in c, we must deploy C with that admin. However rules require c = new C() in setUp().
        // The contract C sets admin = msg.sender at deployment; in setUp it was this test contract. To test the forwarding difference
        // we simulate the admin role by directly calling setOwner from the test contract (which is the admin). Then we forward the call via
        // the helper so that msg.sender != tx.origin inside C for the forwarded case. To make the forwarded call originate from an EOA (admin),
        // we use vm.prank(admin) to set tx.origin for the external call from the EOA into the forwarder, which then calls C.

        // Ensure our fuzzed admin is treated as an EOA for the external call into the forwarder
        vm.prank(admin);
        // From the EOA 'admin' we call the forwarder which will in turn call c.setOwner(proposedOwner).
        // Inside that forwarded call: msg.sender == address(f) and tx.origin == admin.
        // For the correct contract, owner should be set to the provided proposedOwner; the mutant sets owner = tx.origin (admin).
        f.forwardCall(address(c), abi.encodeWithSignature("setOwner(address)", proposedOwner));

        // Now assert the universal property: after this proxied call, c.owner() == proposedOwner for the correct contract.
        // This is a single assertTrue reading c's public getter.
        assertTrue(c.owner() == proposedOwner);
    }
}

// Minimal forwarder helper that calls the target with provided calldata.
contract Forwarder {
    function forwardCall(address target, bytes calldata data) external payable {
        // perform a low-level call to preserve original calldata
        (bool ok, ) = target.call{value: msg.value}(data);
        require(ok, "forward call failed");
    }
}

