pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an EOA that will be tx.origin for the proxied call, and a target owner value
    function testFuzz_property(address originEOA, address intendedOwner) public {
        // keep addresses non-zero to avoid degenerate cases
        vm.assume(originEOA != address(0));
        vm.assume(intendedOwner != address(0));
        // Deploy a small forwarder contract that will call c.setOwner on behalf of originEOA
        Forwarder f = new Forwarder();

        // Ensure the admin (deployer of c) is the msg.sender of the call to setOwner: only admin can call.
        // In setUp(), test contract deployed c, so admin == address(this) (the test contract). We need the test contract
        // to call the forwarder such that tx.origin == originEOA. The fuzzer provides originEOA, so we make the EOA
        // originEOA invoke the forwarder which then calls c.setOwner(intendedOwner).

        // Fund the originEOA so it can send the transaction
        vm.deal(originEOA, 1 ether);

        // We need the admin (= address(this) inside setUp) to be the immediate caller of c.setOwner per onlyAdmin.
        // But only admin can call setOwner. In the reference contract, only msg.sender == admin is allowed. Our test
        // will have the test contract (this) be admin; we must thus have the test contract be the caller of c.setOwner.
        // To model a proxied call where msg.sender == admin but tx.origin != msg.sender, we have to have the test contract
        // call the forwarder while the transaction origin is originEOA. This requires originEOA to externally send a tx
        // that triggers the test contract to call the forwarder. Since the fuzzer only supplies raw addresses, we simulate
        // the realistic proxy scenario by having originEOA call the forwarder (so tx.origin == originEOA) and the forwarder
        // then delegate the call such that msg.sender at c is the admin (the test contract). To accomplish this without
        // using unsupported vm.mockCall, we'll have the test contract instruct the forwarder to call c but signed by the test
        // contract: instead we make the forwarder call c with the test contract as msg.sender by having the test contract
        // be the immediate caller — which can't happen if originEOA is tx.origin. Simpler correct approach: make the test
        // contract the admin and have originEOA call the forwarder which in turn calls c.setOwner; then msg.sender at c is
        // the forwarder, not the admin, so onlyAdmin would block. Therefore we instead use the forwarder to call c via
        // a low-level call that sets msg.sender to the test contract by having the test contract perform the low-level call
        // through the forwarder using a call-from pattern: the test contract will call the forwarder, but we want tx.origin
        // to be originEOA. Foundry supports vm.prank(originEOA, someAddress) to set msg.sender and tx.origin; use vm.prank(originEOA)

        // The correct sequence: originEOA (tx.origin and msg.sender for the next call) calls the test contract with data instructing
        // it to have the test contract call the forwarder which then calls c. However the fuzzer cannot trigger an external call into
        // the test contract. Instead, Foundry's vm.prank(address) sets msg.sender for the next call but keeps tx.origin as the
        // same address as well for the EVM environment. We'll use vm.prank(originEOA) so the next call from this test function will
        // have msg.sender == tx.origin == originEOA. Then the test contract (still executing) can call the forwarder while the EVM
        // environment reports tx.origin == originEOA. That yields a call where the forwarder calls c and tx.origin == originEOA whereas
        // msg.sender at c is the forwarder (not admin) — but only admin check requires msg.sender == admin (admin is set to deployer of c,
        // which was this test contract). To make msg.sender == admin while tx.origin == originEOA, we need the test contract to be the
        // immediate caller of c.setOwner (so msg.sender == admin) and tx.origin == originEOA. Foundry's vm.prank can set msg.sender to originEOA
        // for the upcoming call from this test function; but we need msg.sender at c to be the test contract, not originEOA. This exact scenario
        // is achievable by using a contract (CallerAsAdmin) that the test contract deploys and uses to call c while preserving tx.origin.
        // The flow we implement:
        // 1) originEOA (vm.prank sets msg.sender and tx.origin for the next external invocation) calls the test contract helper entry by
        //    having the test function perform actions under vm.prank(originEOA).
        // 2) Under vm.prank(originEOA), the test contract calls a helper (AdminCaller) that will in turn call c.setOwner. When AdminCaller calls c,
        //    msg.sender at c is AdminCaller (not admin), so onlyAdmin would revert. Instead, we will make AdminCaller a minimal contract we deploy
        //    and then make the test contract itself be the caller of c by directly invoking c.setOwner while vm.prank(originEOA) only sets tx.origin.
        // Foundry supports vm.startPrank(txOrigin) / vm.stopPrank to set msg.sender, but cannot set tx.origin separately. However, when vm.prank(originEOA)
        // is used, both msg.sender and tx.origin are originEOA for the next call. There is no built-in way to make tx.origin be originEOA while msg.sender
        // is this test contract for an internal call. So we take a different approach that achieves the distinguishing condition more straightforwardly:
        // The distinguishing behavior is: correct contract sets owner == provided _owner; mutant sets owner == tx.origin. So if the admin calls setOwner
        // directly (msg.sender == admin) but tx.origin differs from the provided _owner, mutant will set owner to tx.origin which may differ from the
        // provided _owner. We can make tx.origin be originEOA by having the admin (this test contract) call c.setOwner while the tx.origin is originEOA
        // using vm.prank(originEOA, address(this)) which sets tx.origin==originEOA and msg.sender==address(this) for the next call. Foundry's vm.prank supports
        // a two-argument form vm.prank(from, tx.origin) but in practice vm.prank(address) sets both. However vm.prank(addr) followed by an external call from this
        // test contract will make msg.sender==addr, not address(this). To set both tx.origin and msg.sender separately, Foundry provides vm.originate? Not available.
        // Simpler accepted and reliable technique: use a Forwarder contract that the test contract is admin of (i.e., admin is the test contract), and have the
        // test contract invoke c.setOwner using a TX where tx.origin is originEOA but msg.sender is still this test contract via vm.prank(originEOA, address(this)).

        // Use vm.prank with two arguments: first is msg.sender, second is tx.origin. We set msg.sender to address(this) (admin) and tx.origin to originEOA.
        // Foundry supports vm.prank(address) and vm.prank(address, address) in recent versions. Use vm.prank(address(this), originEOA) so that
        // msg.sender is address(this) (satisfying onlyAdmin) and tx.origin is originEOA (so mutant will set owner to originEOA).
        vm.prank(address(this), originEOA);
        // Now call c.setOwner(intendedOwner) as if msg.sender == address(this) (admin) and tx.origin == originEOA
        bool ok;
        try c.setOwner(intendedOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (single assertion): after the call, the correct contract always sets owner == intendedOwner.
        // We observe c.owner() via its public getter. For the reference contract this holds for all admissible inputs. The mutant
        // will set owner == tx.origin (originEOA) and therefore when originEOA != intendedOwner the mutant will violate this assertion.
        assertTrue(ok && (c.owner() == intendedOwner));
    }
}

