pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (who calls setOwner) and candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid the zero-address as a trivial edge (still admissible if fuzz hits it)
        // We must NOT restrict so tightly that the mutant's differing case (caller == current owner != admin)
        // is excluded. Therefore we only normalize addresses to avoid aliasing with address(0) for clarity.
        if (caller == address(0)) caller = address(1);
        if (newOwner == address(0)) newOwner = address(2);

        // At deployment, admin == deployer == address(this test contract)'s msg.sender in setUp (the test runner)
        // and owner == deployer as well. We need to create a scenario where owner != admin so that the mutant
        // (which allows the current owner to call) can differ from the reference (which only allows admin).
        // To do that, have the legitimate admin (the test contract) change owner once to some addr A_admin_set
        // using the real admin privilege so owner != admin. Then we fuzz calls by `caller` to try to change owner
        // to `newOwner`.

        // Step 1: have the admin (the test runner) set owner to some address that is NOT the admin.
        address nonAdminOwner = address(0xBEEF);
        // Ensure nonAdminOwner is not the admin (which is address(this) in test context). It won't be.
        // call as deployer/admin
        // The test contract in setUp deployed C, so the deployer (test runner) is the admin and owner.
        // We (the test) can call setOwner as admin to set owner to nonAdminOwner.
        c.setOwner(nonAdminOwner);

        // Confirm we established owner != admin: owner() should equal nonAdminOwner now.
        // (This is just setup and will hold for both reference and mutant initially)
        // Now the critical point: if caller == nonAdminOwner (current owner) but caller != admin,
        // then in the reference this caller must NOT be allowed to call setOwner to change owner;
        // in the mutant (which checks msg.sender == owner) the caller WILL be allowed and will change owner.

        // Arrange call from `caller` to attempt to set owner to `newOwner`.
        // Provide caller with some ETH so vm.prank can simulate calls from it if needed (not payable here but harmless).
        vm.deal(caller, 1 ether);
        bool ok;
        // perform the call as `caller` and catch whether it succeeded (no revert) or reverted
        // We follow rules: use try/catch around the external call to observe success as a boolean.
        try c.setOwner{value:0}(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for EVERY caller and newOwner, if caller is NOT the original admin,
        // then the call must NOT result in owner() becoming newOwner. Since admin performed an earlier change to
        // set owner to nonAdminOwner, we assert that after the attempted call by `caller` (who may equal nonAdminOwner),
        // the contract's owner is still equal to nonAdminOwner unless the caller was the original admin.
        // We express this as a single assertTrue reading c.owner().

        // Determine who the original admin is: it is the deployer of c, which in setUp() was msg.sender in that context.
        // In Foundry tests, the test contract is the msg.sender for deployments in setUp, so the original admin is address(this).
        address admin = address(this);

        // If caller == admin, the admin is allowed to change owner, so the resulting owner may be newOwner.
        // For all other callers, the reference requires owner to remain nonAdminOwner. Thus we assert that
        // either caller == admin implies nothing (we accept any outcome), OR caller != admin implies c.owner()==nonAdminOwner.

        // Single assertion required: encode the implication as a boolean and assertTrue it.
        bool propertyHolds = (caller == admin) || (c.owner() == nonAdminOwner);
        assertTrue(propertyHolds);
    }
}

