    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor is the admin who calls setOwner, newOwner is the requested owner
    function testFuzz_property(address adminCaller, address newOwner) public {
        // keep domain wide but avoid zero-address for clarity (owner can be zero but we allow it)
        vm.assume(adminCaller != address(0) || true);

        // The contract's deployer (setUp) is the admin; we must call setOwner as that admin.
