pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: actor (possible caller) and newOwner (address to set)
    // General rule: only the original admin (deployer of c, i.e., address(this) at construction) can call setOwner successfully.
    // We'll fuzz an arbitrary caller and an arbitrary target new owner. The reference contract always allows only admin to change owner;
    // the mutant that ORs owner into the require allows a call to setOwner to succeed when msg.sender == owner, which can let a non-admin
    // who has become owner (via some sequence) change owner — the fuzzer will find inputs where a non-admin owner can reassign owner in the mutant
    // but not in the reference. We implement the test by first recording the initial owner, then attempting to call setOwner as the fuzzed actor
    // and finally asserting that only admin (the deployer) can cause the owner to change (i.e., for arbitrary actor != admin, setOwner must not succeed).

    function testFuzz_property(address actor, address newOwner) public {
        // keep addresses wide but avoid zero address for clarity
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        address admin = address(this); // this deployed the contract in setUp(), so it's the admin
        address initialOwner = c.owner();
        // Ensure initialOwner equals deployer of c (setUp used new C() from this contract), which should be address(this)
        // but do not assert that here; we use admin variable as the known privileged principal.

        // Try calling setOwner as the fuzzed actor.
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The universal property: Only the admin may make setOwner succeed. Therefore, for any actor that is NOT the admin,
        // setOwner must not succeed. This will hold for the reference contract for all inputs. The mutant that relaxes the
        // onlyAdmin check to allow owner will let a caller equal to current owner (which might be a non-admin) succeed,
        // causing this assertion to fail for some fuzzed inputs (actor == initialOwner and actor != admin).
        if (actor != admin) {
            assertTrue(!ok);
        } else {
            // admin should be able to setOwner; ensure success for completeness
            assertTrue(ok);
        }
    }
}
